// pkg/boundary/sensors/hanle_optical.go - Hanle Optical Telescope Sensor
//
// Implementation of SensorObserver for the Hanle optical telescope.
// Wraps the existing ZMQ FlatBuffer telemetry stream.

package sensors

import (
	"fmt"
	"math"

	"ssis/pkg/config"
	"ssis/pkg/gen/axiom_zero/Boundary" // Generated by flatc
	"ssis/pkg/physics"

	zmq "github.com/pebbe/zmq4"
)

// HanleOptical implements SensorObserver for the Hanle optical telescope
type HanleOptical struct {
	config     config.SensorConfig
	subscriber *zmq.Socket
	latestObs  Observation
	latestCov  [36]float64
	deviceID   uint32
	sampleRate float64
}

// NewHanleOptical creates a new Hanle optical sensor instance
func NewHanleOptical(config config.SensorConfig) (*HanleOptical, error) {
	// Connect to ZMQ SUB socket
	subscriber, err := zmq.NewSocket(zmq.SUB)
	if err != nil {
		return nil, fmt.Errorf("failed to create SUB socket: %w", err)
	}

	err = subscriber.Connect(config.Endpoint)
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to connect to %s: %w", config.Endpoint, err)
	}

	err = subscriber.SetSubscribe("") // Subscribe to all topics
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to subscribe: %w", err)
	}

	return &HanleOptical{
		config:     config,
		subscriber: subscriber,
		deviceID:   1,     // Hanle telescope ID
		sampleRate: 100.0, // 100Hz nominal rate
		latestCov:  constructOpticalCovariance(),
	}, nil
}

// GetObservation returns the latest observation from Hanle
// Reads from ZMQ stream and converts FlatBuffer to Observation
func (h *HanleOptical) GetObservation() (Observation, error) {
	// Read raw bytes from ZMQ (blocking)
	msg, err := h.subscriber.RecvBytes(0)
	if err != nil {
		// Return cached observation if no new data
		return h.latestObs, nil
	}

	// Zero-Copy Read: Cast byte array into FlatBuffer struct
	packet := Boundary.GetRootAsTelemetryPacket(msg, 0)

	// Convert FlatBuffer to Observation
	obs := Observation{
		TimestampNs: packet.TimestampNs(),
		Wavelength:  550e-9, // Optical wavelength (550nm)
		DeviceID:    h.deviceID,
		Quality:     0.95, // High quality optical tracking
		Covariance:  h.latestCov,
	}

	// Convert spherical (azimuth, elevation) to Cartesian ECI
	// TODO: Get observer position and time for proper conversion
	az := packet.AzimuthMeasured()
	el := packet.ElevationMeasured()

	// Simplified conversion (assumes unit sphere)
	obs.Position = physics.Vector3{
		math.Cos(el) * math.Cos(az),
		math.Cos(el) * math.Sin(az),
		math.Sin(el),
	}

	// Velocity from rate (placeholder - would use proper state estimation)
	obs.Velocity = physics.Vector3{0, 0, 0}

	h.latestObs = obs
	return obs, nil
}

// GetCovariance returns the measurement uncertainty matrix
func (h *HanleOptical) GetCovariance() [36]float64 {
	return h.latestCov
}

// GetWavelength returns the optical wavelength
func (h *HanleOptical) GetWavelength() float64 {
	return 550e-9 // 550nm
}

// GetDeviceID returns the Hanle telescope ID
func (h *HanleOptical) GetDeviceID() uint32 {
	return h.deviceID
}

// GetSampleRate returns the optical sample rate
func (h *HanleOptical) GetSampleRate() float64 {
	return h.sampleRate
}

// Close shuts down the ZMQ connection
func (h *HanleOptical) Close() error {
	if h.subscriber != nil {
		return h.subscriber.Close()
	}
	return nil
}

// constructOpticalCovariance builds default optical covariance
// Optical sensors have better angular resolution than RF
func constructOpticalCovariance() [36]float64 {
	var cov [36]float64

	// Position uncertainty (arcsec converted to radians at 1000km)
	// 1 arcsec = 4.8e-6 rad at 1000km
	posSigma := 5e-6 // ~5 arcsec

	// Velocity uncertainty (rad/s)
	velSigma := 1e-5

	// Diagonal elements (variances)
	cov[0] = posSigma * posSigma
	cov[7] = posSigma * posSigma
	cov[14] = posSigma * posSigma
	cov[21] = velSigma * velSigma
	cov[28] = velSigma * velSigma
	cov[35] = velSigma * velSigma

	return cov
}
